import os
import ast

keywords = ["create_", "update_", "delete_", "save_", "write_", "POST", "PUT", "PATCH"]

def analyze():
    for root, dirs, files in os.walk("app"):
        for file in files:
            if not file.endswith(".py") or file == "auth.py":
                continue
            path = os.path.join(root, file)
            with open(path, "r", encoding="utf-8") as f:
                content = f.read()

            try:
                tree = ast.parse(content)
            except SyntaxError:
                continue

            for node in ast.walk(tree):
                if isinstance(node, ast.FunctionDef):
                    # Check if legacy_auth is called in this function
                    has_legacy_auth = False
                    user_arg = None
                    for child in ast.walk(node):
                        if isinstance(child, ast.Call) and isinstance(child.func, ast.Name) and child.func.id == "legacy_auth":
                            has_legacy_auth = True
                            if child.args:
                                # Get the source code snippet of the argument
                                user_arg = ast.unparse(child.args[0])

                    if has_legacy_auth:
                        # Extract the exact source code of the function
                        func_source = ast.get_source_segment(content, node)
                        # Check for keywords in the function source
                        found_kws = [kw for kw in keywords if kw in func_source]
                        is_write = len(found_kws) > 0
                        print(f"FILE: {path}")
                        print(f"FUNC: {node.name}")
                        print(f"ARG: {user_arg}")
                        print(f"WRITE: {is_write} (matches: {found_kws})")
                        print("-" * 40)

if __name__ == "__main__":
    analyze()

import os

keywords = ["create_", "update_", "delete_", "save_", "write_", "POST", "PUT", "PATCH"]

def check_files():
    for root, dirs, files in os.walk("app"):
        for file in files:
            if not file.endswith(".py") or file == "auth.py":
                continue
            path = os.path.join(root, file)
            with open(path, "r", encoding="utf-8") as f:
                content = f.read()

            found_in_file = [kw for kw in keywords if kw in content]
            found_in_name = [kw for kw in keywords if kw in file]

            if found_in_file or found_in_name:
                print(f"FILE: {path}")
                if found_in_file:
                    print(f"  In file content: {found_in_file}")
                if found_in_name:
                    print(f"  In filename: {found_in_name}")
                print("-" * 30)

if __name__ == "__main__":
    check_files()

import os
import ast

def dump_functions():
    for root, dirs, files in os.walk("app"):
        for file in files:
            if not file.endswith(".py") or file == "auth.py":
                continue
            path = os.path.join(root, file)
            with open(path, "r", encoding="utf-8") as f:
                content = f.read()

            try:
                tree = ast.parse(content)
            except SyntaxError:
                continue

            for node in ast.walk(tree):
                if isinstance(node, ast.FunctionDef):
                    has_legacy_auth = False
                    for child in ast.walk(node):
                        if isinstance(child, ast.Call) and isinstance(child.func, ast.Name) and child.func.id == "legacy_auth":
                            has_legacy_auth = True

                    if has_legacy_auth:
                        print(f"FILE: {path} | FUNC: {node.name}")
                        func_source = ast.get_source_segment(content, node) or ""
                        print(func_source)
                        print("=" * 60)

if __name__ == "__main__":
    dump_functions()

