import os
import ast

keywords = ["create", "update", "delete", "save", "write", "POST", "PUT", "PATCH"]

def migrate():
    for root, dirs, files in os.walk("app"):
        for file in files:
            if not file.endswith(".py") or file == "auth.py":
                continue
            path = os.path.join(root, file)
            with open(path, "r", encoding="utf-8") as f:
                content = f.read()

            try:
                tree = ast.parse(content)
            except SyntaxError:
                continue

            modified = False
            # We want to process each function in the file
            # Let's find all functions that contain legacy_auth calls
            functions_to_migrate = []
            for node in ast.walk(tree):
                if isinstance(node, ast.FunctionDef):
                    calls = []
                    for child in ast.walk(node):
                        if isinstance(child, ast.Call) and isinstance(child.func, ast.Name) and child.func.id == "legacy_auth":
                            calls.append(child)
                    if calls:
                        functions_to_migrate.append((node, calls))

            if not functions_to_migrate:
                continue

            # For each function to migrate, replace legacy_auth calls in content
            # Let's do replacements. Since character offsets can shift after editing,
            # we should process functions from bottom to top or do simple string replacement
            # on the function source segment or the whole file.
            # Actually, since functions are unique and we can get their source segment,
            # let's just do targeted string replaces or replace on the whole file.
            # Wait, let's replace `from app.auth import legacy_auth` first.
            new_content = content
            if "from app.auth import legacy_auth" in new_content:
                new_content = new_content.replace("from app.auth import legacy_auth", "from app.auth import new_auth")
                modified = True

            for func_node, calls in functions_to_migrate:
                func_segment = ast.get_source_segment(content, func_node) or ""
                # Determine scope
                is_write = any(kw.lower() in func_segment.lower() for kw in keywords)
                scope = "write" if is_write else "read"

                # Replace each call in the function segment
                new_func_segment = func_segment
                for call in calls:
                    # Get the exact call text
                    call_text = ast.get_source_segment(content, call)
                    # We want to reconstruct the call with new_auth
                    arg_text = ast.unparse(call.args[0])
                    new_call_text = f"new_auth({arg_text}, scope=\"{scope}\")"

                    if call_text in new_func_segment:
                        new_func_segment = new_func_segment.replace(call_text, new_call_text)
                    else:
                        # Fallback to general replace if exact match fails
                        # e.g. maybe whitespace or parentheses differ slightly
                        target = f"legacy_auth({arg_text})"
                        if target in new_func_segment:
                            new_func_segment = new_func_segment.replace(target, new_call_text)

                # Replace the old function segment in the new_content
                if func_segment in new_content:
                    new_content = new_content.replace(func_segment, new_func_segment)
                    modified = True
                else:
                    print(f"Warning: could not locate function segment in {path}")

            if modified:
                with open(path, "w", encoding="utf-8") as f:
                    f.write(new_content)
                print(f"Migrated {path}")

if __name__ == "__main__":
    migrate()
